package ar.org.inclusoft.api.attendance;
import java.time.*; import java.util.*; import ar.org.inclusoft.api.user.*; import ar.org.inclusoft.api.workshop.*; import jakarta.persistence.EntityManager; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) class AttendanceService { private final WorkshopRepository workshops; private final AttendanceSessionRepository sessions; private final AppUserRepository users; private final EntityManager entityManager; AttendanceService(WorkshopRepository w,AttendanceSessionRepository s,AppUserRepository u,EntityManager e){workshops=w;sessions=s;users=u;entityManager=e;}
 List<AttendanceResponse> findWorkshops(String username,UserRole role,LocalDate date){ return accessible(username,role).stream().filter(w->w.getStatus()==WorkshopStatus.ACTIVE).filter(w->w.getSchedules().stream().anyMatch(s->s.getDayOfWeek()==date.getDayOfWeek())).map(w->load(w,date)).toList(); }
 AttendanceResponse find(String username,UserRole role,UUID id,LocalDate date){Workshop w=accessible(username,role).stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->new AttendanceAccessException("No tenés acceso a este taller.")); return load(w,date);}
 @Transactional AttendanceResponse save(String username,UserRole role,UUID id,LocalDate date,AttendanceRequest request){Workshop w=accessible(username,role).stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->new AttendanceAccessException("No tenés acceso a este taller.")); Set<String> allowed=new HashSet<>(); w.getStudents().forEach(s->allowed.add("STUDENT:"+s.getId())); w.getStaffMembers().forEach(s->allowed.add("STAFF:"+s.getId())); if(request.entries().stream().anyMatch(e->!allowed.contains(e.participantType()+":"+e.participantId()))) throw new AttendanceAccessException("La jornada incluye una persona que no pertenece al taller."); if(request.entries().size()!=allowed.size()) throw new AttendanceAccessException("Completá la asistencia de todos los alumnos y del equipo antes de guardar."); AttendanceSession session=sessions.findByWorkshop_IdAndAttendanceDate(id,date).orElseGet(()->new AttendanceSession(w,date,username)); if(session.getId()!=null){session.getEntries().clear();entityManager.flush();} List<AttendanceEntry> entries=request.entries().stream().map(e->{String name=w.getStudents().stream().filter(s->s.getId().equals(e.participantId())).map(s->s.getLastName()+", "+s.getFirstName()).findFirst().orElseGet(()->w.getStaffMembers().stream().filter(s->s.getId().equals(e.participantId())).map(s->s.getFullName()).findFirst().orElse(""));return new AttendanceEntry(e.participantType(),e.participantId(),name,e.status(),trim(e.observation()));}).toList(); session.update(trim(request.notes()),entries); return response(sessions.save(session),true); }
 private List<Workshop> accessible(String username,UserRole role){if(role!=UserRole.TEACHER)return workshops.findAllByOrderByNameAsc(); AppUser user=users.findByUsernameIgnoreCase(username).orElseThrow(()->new AttendanceAccessException("No se encontró la cuenta docente.")); if(user.getStaffMember()==null)throw new AttendanceAccessException("Tu cuenta docente todavía no está vinculada a una persona del equipo.");return workshops.findDistinctByStaffMembers_Id(user.getStaffMember().getId());} private AttendanceResponse load(Workshop w,LocalDate d){return sessions.findByWorkshop_IdAndAttendanceDate(w.getId(),d).map(s->response(s,true)).orElseGet(()->new AttendanceResponse(w.getId(),w.getName(),d,false,null,roster(w)));} private AttendanceResponse response(AttendanceSession s,boolean saved){return new AttendanceResponse(s.getWorkshop().getId(),s.getWorkshop().getName(),s.getAttendanceDate(),saved,s.getNotes(),s.getEntries().stream().map(e->new AttendanceResponse.Entry(e.getParticipantType(),e.getParticipantId(),e.getParticipantName(),e.getAttendanceStatus(),e.getObservation())).toList());} private List<AttendanceResponse.Entry> roster(Workshop w){List<AttendanceResponse.Entry> all=new ArrayList<>();w.getStudents().forEach(s->all.add(new AttendanceResponse.Entry(AttendanceParticipantType.STUDENT,s.getId(),s.getLastName()+", "+s.getFirstName(),AttendanceStatus.PRESENT,null)));w.getStaffMembers().forEach(s->all.add(new AttendanceResponse.Entry(AttendanceParticipantType.STAFF,s.getId(),s.getFullName(),AttendanceStatus.PRESENT,null)));return all;} private String trim(String value){return value==null||value.isBlank()?null:value.trim();}}
